"""Capture VDU traffic"""
from __future__ import absolute_import, division, print_function, \
    unicode_literals
import os
import ast
from taf.ul.trs_e2e_fw.lib.global_vars import global_vars
from taf.ul.trs_e2e_fw.lib.oam.coam_cbts_vdu.factory import Factory
from taf.ul.trs_e2e_fw.lib.traffic.capture.tool_base import ToolBase
from taf.ul.trs_e2e_fw.lib.utils.config_utils import get_config_variable
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from future import standard_library
from taf.ul.trs_e2e_fw.lib.utils.string_format import decode_str

standard_library.install_aliases()
logger = BackgroundLogger.Instance()


class VduCapture(ToolBase):
    """Capture Vdu traffic"""
    TOOL = "vdu_tool"

    def __init__(self, config, capture_device):
        self.config = config
        self.factory = Factory().get_instance()
        self.capture_device = capture_device
        self.alias_password_dict = {}

    def traffic_capture_start(self, **kwargs):
        """Starts traffic capture"""
        alias = kwargs.pop("alias", "default")
        measurement_point = kwargs["measurement_point"]
        self._setup_oam_ops(self.capture_device, alias)
        timeout = kwargs.pop("timeout", 30)
        capture_type = kwargs["capture_type"]
        plane_type = ast.literal_eval(kwargs.pop("plane_type", None))
        pod_names = ast.literal_eval(kwargs.pop("pod_names", None))
        self.factory.vdu_oam.start_ip_traffic_capture(capture_type=capture_type,
                                                        measurement_point=measurement_point,
                                                        plane_type=plane_type, pod_names=pod_names,
                                                        timeout=timeout, vdu_connection=alias)


    def traffic_capture_stop(self, **kwargs):
        """Stops the traffic capture"""
        alias = kwargs.pop("alias", "default")
        timeout = kwargs.pop("timeout", 30)
        logger.debug("stopping ip capture ....")
        self.factory.vdu_oam.stop_ip_traffic_capture(timeout=timeout, vdu_connection=alias)

    def generate_capture_files(self, **kwargs):
        """abort the traffic capture"""
        alias = kwargs.pop("alias", "default")
        timeout = kwargs.pop("timeout", 30)
        password = kwargs.pop("password", "")
        return self.factory.vdu_oam.generate_ip_traffic_capture_files(credentials=password, timeout=timeout
                                                                   , vdu_connection=alias)

    def traffic_capture_abort(self, **kwargs):
        """abort the traffic capture"""
        alias = kwargs.pop("alias", "default")
        timeout = kwargs.pop("timeout", 30)
        return self.factory.vdu_oam.abort_ip_traffic_capture(timeout=timeout, vdu_connection=alias)

    def upload_traffic_capture_file(self, **kwargs):
        """abort the traffic capture"""
        alias = kwargs.pop("alias", "default")
        timeout = kwargs.pop("timeout", 30)
        local_path = kwargs.pop("local_path", '/home/ute')
        plane_type = ast.literal_eval(kwargs.pop("plane_type", None))
        file_name_dict={'cplane':0,'uplane':1,'mplane':2, 'others':3}
        info = self.factory.vdu_oam.get_ip_traffic_capture_status(timeout=timeout, vdu_connection=alias)
        upload_info = self.factory.vdu_oam.activated_file_upload_operation(timeout=timeout, vdu_connection=alias)
        for a in plane_type:
            result = self.factory.vdu_oam.upload_ip_traffic_capture_file(operation_id=upload_info['operation_id'],
                                                                file_name=info['pod_status'][file_name_dict[a]]['file_name'],
                                                                local_path=local_path, vdu_connection=alias)
        return result
        # dest_file = self._get_capture_dest_file(alias)
        # return dest_file

    def _get_capture_dest_file(self, alias):
        dest_file = 'execution_logs/{}_{}.zip'.format(alias, get_config_variable(["bts_id"]))
        if self.alias_password_dict.get(alias) is not "":
            dest_file = 'execution_logs/{}_{}.zip.enc'.format(alias,
                                                              get_config_variable(["bts_id"]))
        if not os.path.exists(os.path.dirname(dest_file)):
            os.makedirs(os.path.dirname(dest_file))
        return dest_file

    def _setup_oam_ops(self, capture_device, alias):
        logger.debug("setting up oamops....")
        self.factory = Factory.get_instance()
        dut = global_vars.alias_dut_dict.get(alias)
        logger.debug("dut {}".format(dut))
        if dut is None:
            ip = get_config_variable(['traffic_capture', capture_device, "ip"])
            username = get_config_variable(['traffic_capture', capture_device, "admin_user"])
            password = get_config_variable(['traffic_capture', capture_device, "admin_password"])
            port = get_config_variable(['traffic_capture', capture_device, "admin_port"])
            use_ssl = get_config_variable(['traffic_capture', capture_device, "use_ssl"])
            cu_version = get_config_variable(['traffic_capture', capture_device, "vdu_version"])
            logger.info("alias={}".format(alias))

            self.factory.vdu_oam.connect_to(host=ip, port=port, username=username, password=password,
                                           secure=use_ssl, connection_name=alias, vdu_version=cu_version,
                                           login_disabled=False, need_all_info=False, timeout=30)